shapes.code:
Shape[] shapes = [new Rectangle(3, 4), new Triangle(10, 3)];

foreach (var s in shapes)
    Console.WriteLine($"{s.GetType().Name}: {Area(s)}");

static int Area(Shape s) => s switch
{
    Rectangle(var w, var h) => w * h,
    Triangle(var b, var h) => b * h / 2,
    _ => throw new ArgumentException("unknown shape"),
};

abstract record Shape;
record Rectangle(int Width, int Height) : Shape;
record Triangle(int Base, int Height) : Shape;

signature.code:
// async/await: asynchronous code written in direct style.
var slow = FetchAsync("slow", delayMs: 300, value: 40);
var fast = FetchAsync("fast", delayMs: 50, value: 2);

int[] results = await Task.WhenAll(slow, fast);   // both run concurrently
Console.WriteLine($"total = {results.Sum()}");

static async Task<int> FetchAsync(string name, int delayMs, int value)
{
    Console.WriteLine($"{name}: started");
    await Task.Delay(delayMs);        // suspends without blocking a thread
    Console.WriteLine($"{name}: done");
    return value;
}
